10	
11	#include "segment.h"
12	#include <algorithm>
13	#include "hixl_log.h"
14	
15	namespace hixl {
16	
17	Status Segment::AddRange(uint64_t start, uint64_t len) {
18	  // 检查地址溢出
19	  if (len > UINT64_MAX - start) {
20	    HIXL_LOGE(PARAM_INVALID, "Address overflow, addr:%lu, len:%lu", start, len);
21	    return PARAM_INVALID;
22	  }
23	  uint64_t end = start + len;
24	  auto it =
25	      std::upper_bound(ranges_.begin(), ranges_.end(), start,
26	                       [](uint64_t val, const std::pair<uint64_t, uint64_t> &range) { return val < range.first; });
27	  // 检查是否已经存在完全相同的范围
28	  if (it != ranges_.begin()) {
29	    auto prev_it = std::prev(it);
30	    if (prev_it->first == start && prev_it->second == end) {
31	      HIXL_LOGI("Range already exists, start:%lu, end:%lu", start, end);
32	      return SUCCESS;
33	    }
34	  }
35	  if (it != ranges_.end() && it->first == start && it->second == end) {
36	    HIXL_LOGI("Range already exists, start:%lu, end:%lu", start, end);
37	    return SUCCESS;
38	  }
39	  ranges_.insert(it, {start, end});
40	  HIXL_LOGI("Add range success, start:%lu, end:%lu", start, end);
41	  return SUCCESS;
42	}
43	
44	void Segment::RemoveRange(uint64_t start, uint64_t end) {
45	  auto it =
46	      std::lower_bound(ranges_.begin(), ranges_.end(), start,
47	                       [](const std::pair<uint64_t, uint64_t> &range, uint64_t val) { return range.first < val; });
48	  if (it == ranges_.end() || it->first > start) {
49	    HIXL_LOGW("Range not found, start:%lu, end:%lu", start, end);
50	    return;
51	  }
52	  for (; it != ranges_.end() && it->first == start; ++it) {
53	    if (it->second == end) {
54	      ranges_.erase(it);
55	      HIXL_LOGI("Remove range %lu-%lu, left ranges size:%zu", start, end, ranges_.size());
56	      return;
57	    }
58	  }
59	}
60	
61	bool Segment::Contains(uint64_t start, uint64_t end) const {
62	  HIXL_LOGI("Check if segment contains range [%lu, %lu]", start, end);
63	  if (start > end) {
64	    HIXL_LOGE(PARAM_INVALID, "Invalid range, start:%lu, end:%lu", start, end);
65	    return false;
66	  }
67	  auto it =
68	      std::upper_bound(ranges_.begin(), ranges_.end(), start,
69	                       [](uint64_t val, const std::pair<uint64_t, uint64_t> &range) { return val < range.first; });
70	
71	  uint64_t max_reached = start;
72	  bool covered_start = false;
73	  // left range make sure range.start <= start
74	  for (auto r_it = std::make_reverse_iterator(it); r_it != ranges_.rend(); ++r_it) {
75	    if (r_it->second > start) {
76	      if (r_it->second > max_reached) {
77	        max_reached = r_it->second;
78	      }
79	      covered_start = true;
80	      if (max_reached >= end) {
81	        HIXL_LOGI("Segment contains range [%lu, %lu]", start, end);
82	        return true;
83	      }
84	    }
85	  }
86	
87	  if (!covered_start) {
88	    HIXL_LOGI("Range not found, start:%lu, end:%lu", start, end);
89	    return false;
90	  }
91	
92	  for (; it != ranges_.end(); ++it) {
93	    if (it->first > (max_reached + 1)) {
94	      break;
95	    }
96	    if (it->second > max_reached) {
97	      max_reached = it->second;
98	      if (max_reached >= end) {
99	        HIXL_LOGI("Segment contains range [%lu, %lu]", start, end);
100	        return true;
101	      }
102	    }
103	  }
104	  bool result = max_reached >= end;
105	  HIXL_LOGI("Segment contains range [%lu, %lu]", start, end);
106	  return result;
107	}
108	
109	MemType Segment::GetMemType() const {
110	  return mem_type_;
111	}
112	
113	}  // namespace hixl
