19	namespace {
20	bool IsAddrInRegion(const MemoryRegion &region, const void *addr) {
21	  if (addr < region.addr) {
22	    return false;
23	  }
24	  auto region_end = static_cast<const void *>(static_cast<const uint8_t *>(region.addr) + region.size);
25	  return addr < region_end;
26	}
27	
28	// 检查内存区域是否连续（addr和register_dev_addr都必须连续）
29	bool CheckRegionsContiguous(const MemoryRegion &prev, const MemoryRegion &curr) {
30	  // 首先检查addr连续性（这是基本前提）
31	  uintptr_t prev_end = reinterpret_cast<uintptr_t>(prev.addr) + prev.size;
32	  uintptr_t curr_start = reinterpret_cast<uintptr_t>(curr.addr);
33	  if (prev_end != curr_start) {
34	    return false;  // addr不连续，直接返回 false
35	  }
36	
37	  // 如果addr连续，检查register_dev_addr连续性（当有register_dev_addr地址时）
38	  if (prev.register_dev_addr != nullptr && curr.register_dev_addr != nullptr) {
39	    uintptr_t prev_dev_end = reinterpret_cast<uintptr_t>(prev.register_dev_addr) + prev.size;
40	    uintptr_t curr_dev_start = reinterpret_cast<uintptr_t>(curr.register_dev_addr);
41	    return prev_dev_end == curr_dev_start;  // register_dev_addr也必须连续
42	  }
43	
44	  // 如果没有 register_dev_addr 地址，addr地址连续即可
45	  return true;
46	}
47	}  // namespace
48	Status HixlMemStore::RecordMemory(bool is_server, const void *addr, size_t size, bool is_host_mem,
49	                                  void *register_dev_addr) {
50	  std::lock_guard<std::mutex> lock(mutex_);
51	  MemoryRegion new_region(addr, size, is_host_mem, register_dev_addr);
52	  if (is_server) {  // server侧内存注册
53	    auto it = server_regions_.find(addr);
54	    if (it != server_regions_.end()) {
55	      HIXL_LOGI("This server mem is already registered, addr:%p, size:%zu.", addr, size);
56	      return SUCCESS;  // 内存已注册，此时不做处理，直接返回。
57	    }
58	    server_regions_[addr] = new_region;
59	    HIXL_LOGI("Server mem registered successfully, addr:%p, size:%zu.", addr, size);
60	  } else {  // client侧内存注册
61	    auto it = client_regions_.find(addr);
62	    if (it != client_regions_.end()) {
63	      HIXL_LOGI("This client mem is already registered, addr:%p, size:%zu.", addr, size);
64	      return PARAM_INVALID;  // 内存已注册
65	    }
66	    client_regions_[addr] = new_region;
67	    HIXL_LOGI("Client mem registered successfully, addr:%p, size:%zu.", addr, size);
68	  }
69	  return SUCCESS;
70	}
71	
72	Status HixlMemStore::UnrecordMemory(bool is_server, const void *addr) {
73	  std::lock_guard<std::mutex> lock(mutex_);
74	  if (is_server) {
75	    auto it = server_regions_.find(addr);
76	    HIXL_CHK_BOOL_RET_STATUS(it != server_regions_.end(), PARAM_INVALID,
77	                             "The memory has not been registered and cannot be deleted, buf_addr:%p", addr);
78	    server_regions_.erase(addr);
79	  } else {
80	    auto it = client_regions_.find(addr);
81	    HIXL_CHK_BOOL_RET_STATUS(it != client_regions_.end(), PARAM_INVALID,
82	                             "The memory has not been registered and cannot be deleted, buf_addr:%p", addr);
83	    client_regions_.erase(addr);
84	  }
85	  HIXL_LOGI("This mem has been deleted, addr:%p.", addr);
86	  return SUCCESS;
87	}
88	
89	bool HixlMemStore::CheckMemoryForRegister(bool is_server, const void *check_addr, size_t check_size) const {
90	  std::lock_guard<std::mutex> lock(mutex_);
91	  const auto &regions = is_server ? server_regions_ : client_regions_;
92	  HIXL_CHECK_NOTNULL(check_addr);
93	  if (check_size == size_t{0}) {
94	    return true;
95	  }  // 地址大小为0，无效，视为不允许注册
96	  if (regions.empty()) {
97	    return false;
98	  }  // regions为空，没有已注册，允许注册
99	
100	  uintptr_t s = reinterpret_cast<uintptr_t>(check_addr);
101	  uintptr_t e = 0;
102	  if (ge::AddOverflow(s, check_size, e)) {
103	    HIXL_LOGE(PARAM_INVALID, "Address overflow in CheckMemoryForRegister, addr:%p, size:%zu.", check_addr, check_size);
104	    return true;
105	  }
106	
107	  auto overlaps = [s, e](const MemoryRegion &r) {
108	    auto rs = reinterpret_cast<uintptr_t>(r.addr);
109	    uintptr_t re = 0;
110	    if (ge::AddOverflow(rs, r.size, re)) {
111	      return true;
112	    }
113	    bool is_overlap = (s < re) && (rs < e);  // 内存重叠，返回true
114	    bool is_same = (s == rs) && (e == re);  // 当内存块与已注册内存块完全一致时，此时允许重新注册，返回false
115	    return is_overlap && !is_same;
116	  };
117	
118	  auto it = regions.lower_bound(check_addr);
119	  if (it != regions.end() && overlaps(it->second)) {
120	    HIXL_LOGE(PARAM_INVALID,
121	              "%s memory registration failed; the parameters overlap with the already registered memory. "
122	              "Overlapping memory information: buf_addr:%p, buf_len:%zu",
123	              is_server ? "Server" : "Client", it->second.addr, it->second.size);
124	    return true;  // 与后一个起点>=s的区间重叠
125	  }
126	  if (it != regions.begin()) {
127	    const auto &prev = std::prev(it)->second;  // 与前一个区间可能重叠
128	    if (overlaps(prev)) {
129	      HIXL_LOGE(PARAM_INVALID,
130	                "%s memory registration failed; the parameters overlap with the already registered memory. "
131	                "Overlapping memory information: buf_addr:%p, buf_len:%zu",
132	                is_server ? "Server" : "Client", prev.addr, prev.size);
133	      return true;
134	    }
135	  }
136	  return false;  // 与相邻区域都不重叠，或者内存与已注册内存完全一致，允许注册
137	}
138	
139	bool HixlMemStore::CheckMemoryForAccess(bool is_server, const void *check_addr, size_t check_size) const {
140	  const auto &regions = is_server ? server_regions_ : client_regions_;
141	  HIXL_CHECK_NOTNULL(check_addr);
142	  if (check_size == size_t{0}) {
143	    return false;
144	  }
145	  if (regions.empty()) {
146	    return false;  // 无注册，访问不允许
147	  }
148	
149	  uintptr_t s = reinterpret_cast<uintptr_t>(check_addr);
150	  if (check_size > std::numeric_limits<uintptr_t>::max() - s) {
151	    return false;  // overflow would occur, deny access
152	  }
153	  uintptr_t e = s + check_size;  // [s, e)
154	
155	  auto it = regions.lower_bound(check_addr);
156	  auto contains = [s, e](const MemoryRegion &r) {
157	    auto rs = reinterpret_cast<uintptr_t>(r.addr);
158	    auto re = rs + r.size;
159	    return (s >= rs) && (e <= re);
160	  };
161	
162	  if (it != regions.end() && contains(it->second)) {
163	    return true;
164	  }
165	  if (it != regions.begin()) {
166	    const auto &prev = std::prev(it)->second;
167	    if (contains(prev)) {
168	      return true;
169	    }
170	  }
171	  if (it != regions.end()) {
172	    return CheckMergedRegionsAccess(regions, s, e, it);
173	  }
174	  return false;
175	}
176	
177	bool HixlMemStore::CheckMergedRegionsAccess(const std::map<const void *, MemoryRegion> &regions, uintptr_t s,
178	                                            uintptr_t e, std::map<const void *, MemoryRegion>::const_iterator it) {
179	  auto get_addr = [](const MemoryRegion &r) { return reinterpret_cast<uintptr_t>(r.addr); };
180	  auto get_region_end = [&get_addr](const MemoryRegion &r) { return get_addr(r) + r.size; };
181	  auto contains = [s, e, get_addr, get_region_end](const MemoryRegion &r) {
182	    return (s >= get_addr(r)) && (e <= get_region_end(r));
183	  };
184	
185	  // Find contiguous region from it backward
186	  auto start_it = it;
187	  while (start_it != regions.begin()) {
188	    auto prev_it = std::prev(start_it);
189	    if (!CheckRegionsContiguous(prev_it->second, start_it->second)) {
190	      break;
191	    }
192	    start_it = prev_it;
193	  }
194	
195	  // Find contiguous region from it forward
196	  auto end_it = it;
197	  while (end_it != regions.end()) {
198	    auto next_it = std::next(end_it);
199	    if (next_it == regions.end() || !CheckRegionsContiguous(end_it->second, next_it->second)) {
200	      break;
201	    }
202	    end_it = next_it;
203	  }
204	
205	  if (start_it == end_it || end_it == regions.end()) {
206	    return false;
207	  }
208	
209	  auto merged_start = get_addr(start_it->second);
210	  auto merged_end = get_region_end(end_it->second);
211	  MemoryRegion merged(start_it->second.addr, merged_end - merged_start);
212	
213	  if (contains(merged)) {
214	    HIXL_LOGI("Merged regions for access check: [%p, 0x%lx)", start_it->second.addr, merged_end);
215	    return true;
216	  }
217	  return false;
218	}
219	
220	Status HixlMemStore::ValidateMemoryAccess(const void *server_addr, size_t mem_size, const void *client_addr) const {
221	  std::lock_guard<std::mutex> lock(mutex_);
222	  HIXL_CHK_BOOL_RET_STATUS(server_addr != nullptr && client_addr != nullptr && mem_size != size_t{0}, PARAM_INVALID,
223	                           "Memory access validation failed, server_addr:%p, client_addr:%p, buf_len:%zu bytes",
224	                           server_addr, client_addr, mem_size);
225	  bool server_valid = CheckMemoryForAccess(true, server_addr, mem_size);
226	  // 验证Server端内存访问t
227	  HIXL_CHK_BOOL_RET_STATUS(server_valid, PARAM_INVALID,
228	                           "Server memory verification failed, memory is not registered, server_addr:%p, "
229	                           "buf_len:%zu bytes",
230	                           server_addr, mem_size);
231	  // 验证Client端内存访问
232	  bool client_valid = CheckMemoryForAccess(false, client_addr, mem_size);
233	  HIXL_CHK_BOOL_RET_STATUS(client_valid, PARAM_INVALID,
234	                           "Client memory verification failed, memory is not registered, client_addr:%p, "
235	                           "buf_len:%zu bytes",
236	                           client_addr, mem_size);
237	  return SUCCESS;
238	}
239	
240	Status HixlMemStore::FindMemoryRegion(bool is_server, const void *addr, MemoryRegion &region) const {
241	  const auto &regions = is_server ? server_regions_ : client_regions_;
242	  if (regions.empty()) {
243	    return FAILED;
244	  }
245	  auto it = regions.lower_bound(addr);
246	  if (it != regions.end() && IsAddrInRegion(it->second, addr)) {
247	    region = it->second;
248	    return SUCCESS;
249	  }
250	  if (it != regions.begin()) {
251	    const auto &prev = std::prev(it)->second;
252	    if (IsAddrInRegion(prev, addr)) {
253	      region = prev;
254	      return SUCCESS;
255	    }
256	  }
257	  return FAILED;
258	}
259	
260	Status HixlMemStore::BatchValidateMemoryAccess(uint32_t list_num, const HixlOneSideOpDesc *desc_list) const {
261	  std::lock_guard<std::mutex> lock(mutex_);
262	  for (uint32_t i = 0; i < list_num; ++i) {
263	    const void *server_addr = desc_list[i].remote_buf;
264	    const void *client_addr = desc_list[i].local_buf;
265	    size_t mem_size = static_cast<size_t>(desc_list[i].len);
266	    HIXL_CHK_BOOL_RET_STATUS(server_addr != nullptr && client_addr != nullptr && mem_size != size_t{0}, PARAM_INVALID,
267	                             "Batch validation failed, idx:%u, server_addr:%p, client_addr:%p, buf_len:%zu bytes", i,
268	                             server_addr, client_addr, mem_size);
269	    bool server_valid = CheckMemoryForAccess(true, server_addr, mem_size);
270	    HIXL_CHK_BOOL_RET_STATUS(server_valid, PARAM_INVALID,
271	                             "Server memory verification failed, memory is not registered, idx:%u, server_addr:%p, "
272	                             "buf_len:%zu bytes",
273	                             i, server_addr, mem_size);
274	    bool client_valid = CheckMemoryForAccess(false, client_addr, mem_size);
275	    HIXL_CHK_BOOL_RET_STATUS(client_valid, PARAM_INVALID,
276	                             "Client memory verification failed, memory is not registered, idx:%u, client_addr:%p, "
277	                             "buf_len:%zu bytes",
278	                             i, client_addr, mem_size);
279	  }
280	  return SUCCESS;
281	}
282	
283	Status HixlMemStore::ConvertHostAddr(HixlOneSideOpDesc &desc, uint32_t &local_host_cnt,
284	                                     uint32_t &remote_host_cnt) const {
285	  MemoryRegion remote_region;
286	  Status status = FindMemoryRegion(true, desc.remote_buf, remote_region);
287	  if (status != SUCCESS) {
288	    HIXL_LOGE(status, "[HixlMemStore] remote addr %p not registered", desc.remote_buf);
289	    return status;
290	  }
291	  if (remote_region.is_host_mem) {
292	    HIXL_CHECK_NOTNULL(remote_region.register_dev_addr, ", register_dev_addr is nullptr.");
293	    uintptr_t offset = reinterpret_cast<uintptr_t>(desc.remote_buf) - reinterpret_cast<uintptr_t>(remote_region.addr);
294	    void *host_addr = desc.remote_buf;
295	    desc.remote_buf = static_cast<void *>(static_cast<char *>(remote_region.register_dev_addr) + offset);
296	    HIXL_LOGD("[HixlMemStore] Convert remote addr: %p -> %p, region_size=%zu, desc_len=%lu", host_addr, desc.remote_buf,
297	              remote_region.size, desc.len);
298	    remote_host_cnt++;
299	  }
300	
301	  MemoryRegion local_region;
302	  status = FindMemoryRegion(false, desc.local_buf, local_region);
303	  if (status != SUCCESS) {
304	    HIXL_LOGE(status, "[HixlMemStore] local addr %p not registered", desc.local_buf);
305	    return status;
306	  }
307	  if (local_region.is_host_mem) {
308	    HIXL_CHECK_NOTNULL(local_region.register_dev_addr, ", register_dev_addr is nullptr.");
309	    uintptr_t offset = reinterpret_cast<uintptr_t>(desc.local_buf) - reinterpret_cast<uintptr_t>(local_region.addr);
310	    void *host_addr = desc.local_buf;
311	    desc.local_buf = static_cast<void *>(static_cast<char *>(local_region.register_dev_addr) + offset);
312	    HIXL_LOGD("[HixlMemStore] Convert local addr: %p -> %p, region_size=%zu, desc_len=%lu", host_addr, desc.local_buf,
313	              local_region.size, desc.len);
314	    local_host_cnt++;
315	  }
316	  return SUCCESS;
317	}
