319	Status HixlMemStore::BatchConvertHostAddr(uint32_t list_num, HixlOneSideOpDesc *desc_list) const {
320	  std::lock_guard<std::mutex> lock(mutex_);
321	  uint32_t local_host_cnt = 0U;
322	  uint32_t remote_host_cnt = 0U;
323	  for (uint32_t i = 0; i < list_num; ++i) {
324	    Status status = ConvertHostAddr(desc_list[i], local_host_cnt, remote_host_cnt);
325	    if (status != SUCCESS) {
326	      return status;
327	    }
328	  }
329	  HIXL_LOGI(
330	      "[HixlMemStore] BatchConvertHostAddr success, list_num=%u, local host mem count=%u, remote host mem count=%u",
331	      list_num, local_host_cnt, remote_host_cnt);
