#ifndef CANN_HIXL_SRC_HIXL_CS_HIXL_MEM_STORE_H_
#define CANN_HIXL_SRC_HIXL_CS_HIXL_MEM_STORE_H_
#include <cstdint>
#include <mutex>
#include "hixl/hixl_types.h"
#include "cs/hixl_cs.h"

namespace hixl {
struct MemoryRegion {
  const void *addr = nullptr;  // 内存起始地址
  size_t size = 0U;            // 内存区域大小
  bool is_host_mem = false;
  void *register_dev_addr = nullptr;  // 非空时有效

  MemoryRegion() = default;
  MemoryRegion(const void *a, size_t s, bool is_host = false, void *dev_addr = nullptr) noexcept
      : addr(a), size(s), is_host_mem(is_host), register_dev_addr(dev_addr) {}
};

/**
 * @brief 内存存储管理类
 *
 * 负责管理Server和Client端注册的内存区域，提供内存访问验证功能，与client绑定，作为client的成员变量，一个Client有一个memstore对象，用于记录client侧的endpoint分配的内存地址和sever侧分配的内存地址。channel销毁后，销毁memstore
 */
class HixlMemStore {
 public:
  HixlMemStore() = default;
  ~HixlMemStore() = default;

  /**
   * @brief 给client的endpoint分配内存时，登记Client端分配的内存区域
   * @param is_server 判断是哪一侧注册内存
   * @param addr 要注册的内存起始地址
   * @param size 要注册的内存区域大小
   * @return 操作结果
   */
  Status RecordMemory(bool is_server, const void *addr, size_t size, bool is_host_mem = false,
                      void *register_dev_addr = nullptr);

  /**
   * @brief channel销毁后，注销Server端已经注册的内存区域
   */
  Status UnrecordMemory(bool is_server, const void *addr);

  /**
   * @brief 验证Client对Server的内存访问请求是否在注册范围内
   * @param server_addr 请求访问的Server端内存地址
   * @param mem_size 请求访问的Server端内存大小
   * @param client_addr 发起请求的Client端内存地址
   * @return 验证结果
   */
  Status ValidateMemoryAccess(const void *server_addr, size_t mem_size, const void *client_addr) const;
  bool CheckMemoryForRegister(bool is_server, const void *check_addr, size_t check_size) const;
  Status BatchValidateMemoryAccess(uint32_t list_num, const HixlOneSideOpDesc *desc_list) const;
  // 本函数默认已经经过了BatchValidateMemoryAccess校验，所以不做地址长度校验。
  Status BatchConvertHostAddr(uint32_t list_num, HixlOneSideOpDesc *desc_list) const;

 private:
  bool CheckMemoryForAccess(bool is_server, const void *check_addr, size_t check_size) const;
  Status FindMemoryRegion(bool is_server, const void *addr, MemoryRegion &region) const;
  Status ConvertHostAddr(HixlOneSideOpDesc &desc, uint32_t &local_host_cnt, uint32_t &remote_host_cnt) const;
  static bool CheckMergedRegionsAccess(const std::map<const void *, MemoryRegion> &regions, uintptr_t s, uintptr_t e,
                                       typename std::map<const void *, MemoryRegion>::const_iterator it);
  // 内存区域信息结构体
  std::map<const void *, MemoryRegion> server_regions_;
  std::map<const void *, MemoryRegion> client_regions_;
  mutable std::mutex mutex_;

  HixlMemStore(const HixlMemStore &) = delete;
  HixlMemStore &operator=(const HixlMemStore &) = delete;
};
}  // namespace hixl
#endif  // CANN_HIXL_SRC_HIXL_CS_HIXL_MEM_STORE_H_

