102	Status HixlServer::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
103	  HIXL_CHECK_NOTNULL(server_handle_);
104	  AddrInfo cur_info{};
105	  cur_info.start_addr = mem.addr;
106	  HIXL_CHK_BOOL_RET_STATUS(!ge::AddOverflow(mem.addr, mem.len, cur_info.end_addr), PARAM_INVALID,
107	                           "Address overflow in RegisterMem, addr:0x%lx, len:%lu.", mem.addr, mem.len);
108	  cur_info.mem_type = type;
109	  std::lock_guard<std::mutex> lk(mtx_);
110	
111	  bool is_duplicate = false;
112	  MemHandle existing_handle = nullptr;
113	  HIXL_CHK_STATUS_RET(CheckAddrOverlap(cur_info, handle_to_addr_, is_duplicate, existing_handle),
114	                      "Failed to check address overlap.");
115	  if (is_duplicate) {
116	    mem_handle = existing_handle;
117	    HIXL_LOGI("Memory already registered, returning existing handle:%p", mem_handle);
118	    return SUCCESS;
119	  }
120	
121	  CommMem hccl_mem{};
122	  hccl_mem.type = (type == MemType::MEM_DEVICE) ? COMM_MEM_TYPE_DEVICE : COMM_MEM_TYPE_HOST;
123	  hccl_mem.addr = reinterpret_cast<void *>(mem.addr);
124	  hccl_mem.size = mem.len;
125	  HIXL_CHK_STATUS_RET(HixlCSServerRegMem(server_handle_, nullptr, &hccl_mem, &mem_handle),
126	                      "Failed to register mem, addr:0x%lx, size:%lu, type:%d.", mem.addr, mem.len,
127	                      static_cast<int32_t>(type));
128	  handle_to_addr_[mem_handle] = cur_info;
129	  return SUCCESS;
130	}
131	
132	Status HixlServer::DeregisterMem(MemHandle &mem_handle) {
133	  HIXL_CHECK_NOTNULL(server_handle_);
134	  // 判断mem_handle是否存在
135	  std::lock_guard<std::mutex> lk(mtx_);
136	  auto it = handle_to_addr_.find(mem_handle);
137	  if (it == handle_to_addr_.end()) {
138	    HIXL_LOGW("mem_handle:%p is not registered.", mem_handle);
139	    return SUCCESS;
140	  }
141	  HIXL_CHK_STATUS_RET(HixlCSServerUnregMem(server_handle_, mem_handle), "Failed to deregister mem, handle:%p.",
142	                      mem_handle);
143	  handle_to_addr_.erase(it);
144	  mem_handle = nullptr;
145	  return SUCCESS;
146	}
147	
148	Status HixlServer::Finalize() {
149	  if (server_handle_ == nullptr) {
150	    return SUCCESS;
151	  }
152	  // 注销所有注册的内存
153	  std::lock_guard<std::mutex> lk(mtx_);
154	  for (const auto &handle : handle_to_addr_) {
155	    Status ret = HixlCSServerUnregMem(server_handle_, handle.first);
156	    if (ret != SUCCESS) {
157	      HIXL_LOGE(ret, "Failed to deregister mem, handle:%p.", handle);
158	    }
159	  }
160	  handle_to_addr_.clear();
161	  HIXL_CHK_STATUS_RET(HixlCSServerDestroy(server_handle_), "Failed to destroy hixl server.");
162	  server_handle_ = nullptr;
163	  return SUCCESS;
164	}

